'use strict';
function mealMarkup(){return `<section class="mealCard"><div><h3>GREENHOUSE MESS</h3><p>Personal nutrition: <b>${Math.round(player.nutrition??100)} / 100</b><br>One ration: <b>5 food from storage → +35 nutrition</b>. Grow and harvest crops to restock the pantry.</p></div><button id="eatMeal" ${(state.food<5||(player.nutrition??100)>=100)?'disabled':''}>F · EAT RATION</button></section>`}
async function eatMeal(){if(mp?.busy)return;const before=player.nutrition??100;await expeditionDo('eat');showModule('food');if((player.nutrition??100)>before)notify('Ration eaten. +35 nutrition (up to 100) and −5 food from storage.')}
addEventListener('keydown',e=>{if(e.key.toLowerCase()==='f'&&!e.repeat&&$('dialog').open&&$('eatMeal')&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();if(!$('eatMeal').disabled)eatMeal()}});
function personalMissionObjective(){const a=player.assignment,j=RT.missions.find(m=>m.id===a?.id);return !a?'Go to the Command Center for your mission.':a.status==='active'?j.goal:a.status==='collected'?'Deposit your samples in the Laboratory.':a.status==='deposited'?'Analyze the deposited sample in the Laboratory.':'Mission complete. Return to the Command Center for your next assignment.'}
function personalMissionMarkup(){const a=player.assignment,j=RT.missions.find(m=>m.id===a?.id);return `<section class="personalMission"><h3>${j?.title||'Your next expedition'}</h3><p>${personalMissionObjective()}</p>${a?`<ol><li>✓ Get your assignment</li><li>${a.status==='active'?'▢':'✓'} ${j.goal} Press E at the marker.</li><li>${a.status==='done'?'✓':'▢'} Deposit and analyze in the Laboratory</li></ol>`:'<p>Each astronaut gets an individual assignment. Your progress is saved when you reconnect.</p>'}<p>Each analysis earns <b>+20 science and data, +8 materials, +2 parts and +4 safety</b>. Each analysis consumes one sample. Difficulty increases every three days.</p></section>`}
function drawPersonalTarget(g){const a=player.assignment,j=RT.missions.find(m=>m.id===a?.id);if(!a||a.status==='done'||!j)return;const dest=a.status==='active'?{scene:'ext',x:j.x,y:j.y}:world.scene==='ext'?{scene:'ext',x:416,y:550}:{scene:'base',x:1104,y:192};if(world.scene!==dest.scene)return;g.save();g.translate(dest.x,dest.y-32);g.fillStyle='#61ffe2';g.font='bold 9px monospace';g.textAlign='center';g.fillText(a.status==='active'?'YOUR OBJECTIVE · E':'LABORATORY · SAMPLES',0,-12);g.rotate(Math.PI/4);g.fillRect(-5,-5,10,10);g.restore()}
let interactionPulse=null;
const previousOpen=open;open=function(html){previousOpen(html);$('modal').classList.remove('moduleEnter');void $('modal').offsetWidth;$('modal').classList.add('moduleEnter');if(playing)interactionPulse={x:player.x,y:player.y,scene:world.scene,at:time}};
function drawInteractionPulse(g){const p=interactionPulse;if(!p||p.scene!==world.scene)return;const age=time-p.at;if(age>1)return;g.save();g.globalAlpha=1-age;g.strokeStyle='#77ffe2';g.lineWidth=2;g.strokeRect(p.x-14-age*16,p.y-10-age*10,28+age*32,20+age*20);for(let i=0;i<6;i++){g.fillStyle=i%2?'#f6cf48':'#79dcff';g.fillRect(p.x+Math.cos(i)*age*35,p.y-12-Math.sin(i)*age*25,3,3)}g.restore()}
function styleProcedure(id){if(id==='battery'){const span=$('insertBattery')?.querySelector('span');if(span)span.innerHTML=`<img draggable="false" class="batteryPixel" src="${PIX.props.battery.toDataURL()}" alt="Reserve battery">`;}if(id==='engine'){const c=document.createElement('canvas');c.width=64;c.height=72;const g=c.getContext('2d');const r=(x,y,w,h,color)=>{g.fillStyle=color;g.fillRect(x,y,w,h)};r(17,4,30,40,'#0b1229');r(20,7,24,34,'#4c7094');r(23,9,18,30,'#8aaec9');for(let y=11;y<37;y+=7)r(19,y,26,3,'#1a3555');r(8,15,8,31,'#243f63');r(11,17,3,26,'#49cfff');r(48,15,8,31,'#243f63');r(50,17,3,26,'#ffb445');r(24,40,16,9,'#162a48');r(21,49,22,5,'#4c7094');r(18,54,28,5,'#8aaec9');r(14,59,36,5,'#4c7094');r(11,64,42,5,'#112440');const img=document.createElement('img');img.className='enginePixel';img.alt='Rescue engine and supply lines';img.src=c.toDataURL();$('operationBench').querySelector('.engineNozzle')?.prepend(img);}}

// Three personal gauges, separate from the shared base resources.
const personalHUD=document.createElement('section');personalHUD.id='personalHUD';personalHUD.setAttribute('aria-label','Astronaut vitals');$('hud').append(personalHUD);
const pixelShapes={health:'M2 2H6V3H7V4H9V3H10V2H14V3H15V8H14V10H12V12H10V14H8V15H7V14H5V12H3V10H1V8H0V4H1V3H2Z',nutrition:'M8 1H13V2H15V4H16V8H14V10H11V11H8V10H7V9H6V10H5V12H4V14H2V13H0V11H1V9H3V8H5V7H6V4H7V2H8Z',suit:'M6 0H10V2H11V4H12V14H11V16H5V15H4V5H5V3H6ZM6 7H10V12H6Z'};
function unitIcon(kind){return `<svg viewBox="0 0 16 16" aria-hidden="true" shape-rendering="crispEdges"><path fill="currentColor" fill-rule="evenodd" d="${pixelShapes[kind]}"/></svg>`}
function personalRow(kind,title,value){const v=Math.max(0,Math.min(100,value));return `<div class="personalRow ${kind} ${v<=20?'low':''}" role="meter" aria-label="${title}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(v)}"><span class="rowLabel">${title}</span><span class="units">${Array.from({length:10},(_,i)=>`<span class="vitalUnit">${unitIcon(kind)}<span class="unitFill" style="width:${Math.max(0,Math.min(100,(v-i*10)*10))}%">${unitIcon(kind)}</span></span>`).join('')}</span><b>${Math.round(v)}</b></div>`}
let lastPersonalHealth=null;
function updatePersonalHUD(){const hp=player.health??100,food=player.nutrition??100,air=player.suit??100,buffer=player.airBuffer??20;const name=mp?.code?mp.room?.players?.[mp.uid]?.name:settings.name||crew[role].name;
 personalHUD.innerHTML=`<div class="personalHeading"><span id="personalName"></span><small>${player.dead?'DECEASED · SPECTATOR':world.scene==='ext'?'OUTSIDE':'IN THE BASE'}</small></div>${personalRow('health','HEALTH',hp)}${personalRow('nutrition','NUTRITION',food)}${personalRow('suit','OXYGEN',air)}<div class="personalHint">${world.scene==='ext'?(buffer>0?'O₂ buffer: ' + Math.ceil(buffer) + ' s before the tank starts draining.':'Tank in use. Return through the airlock to refill.'):'Bedroom restores health · Press F to eat in the Greenhouse · Suit refilling'}</div>${player.rover?'<div class="personalVehicle">ROVER '+Math.round(state.rover.battery)+'% · R TO EXIT</div>':''}`;
 $('personalName').textContent='YOUR ASTRONAUT · '+(name||'Explorer');if(lastPersonalHealth!==null&&hp<lastPersonalHealth-.1){personalHUD.classList.remove('damageFlash');void personalHUD.offsetWidth;personalHUD.classList.add('damageFlash')}lastPersonalHealth=hp;
}

function sampleMarkup(){return `<section class="mealCard"><div><h3>SURFACE SAMPLES</h3><p>Backpack: ${(player.samples||[]).length} · Deposited: ${(state.sampleQueue||[]).length}. Deposit your rocks and dust, then select Analyze lunar samples. Each analysis consumes a sample and earns science and resources.</p></div><button id="depositSamples" ${(player.samples||[]).length?'':'disabled'}>DEPOSIT SAMPLES</button></section>`}
